import type { Vec3 } from '../contracts/math';
import type { CameraCollisionOptions, CameraRaycaster } from './CameraCollision';
import { resolveCameraPosition } from './CameraCollision';
import type { CameraPose } from './CameraPose';
import { cloneCameraPose } from './CameraPose';
import type { CameraTransitionOptions } from './CameraTransition';
import { CameraTransition } from './CameraTransition';
import { clampDeltaSeconds, createVec3SpringState, damp, smoothDampVec3 } from './Smoothing';

export interface SmoothCameraRigOptions {
  positionSmoothTime?: number;
  targetSmoothTime?: number;
  fovSmoothTime?: number;
  maxSpeed?: number;
  maxDeltaSeconds?: number;
  raycaster?: CameraRaycaster;
  collision?: CameraCollisionOptions;
}

interface ResolvedRigOptions {
  positionSmoothTime: number;
  targetSmoothTime: number;
  fovSmoothTime: number;
  maxSpeed: number;
  maxDeltaSeconds: number;
  raycaster?: CameraRaycaster;
  collision?: CameraCollisionOptions;
}

const DEFAULT_OPTIONS: ResolvedRigOptions = {
  positionSmoothTime: 0.28,
  targetSmoothTime: 0.18,
  fovSmoothTime: 0.25,
  maxSpeed: 60,
  maxDeltaSeconds: 0.1,
};

/**
 * Keeps the camera pose smooth: springs follow the desired pose every frame,
 * timed transitions take over when the game switches viewpoint, and the result
 * is pushed out of geometry through the shared collision resolver. The rig has
 * no opinion about camera modes - callers hand it a desired pose per frame.
 */
export class SmoothCameraRig {
  readonly transition = new CameraTransition();

  private pose: CameraPose;
  private options: ResolvedRigOptions;
  private readonly positionSpring = createVec3SpringState();
  private readonly targetSpring = createVec3SpringState();

  constructor(initialPose: CameraPose, options: SmoothCameraRigOptions = {}) {
    this.pose = cloneCameraPose(initialPose);
    this.options = { ...DEFAULT_OPTIONS, ...options };
  }

  get current(): CameraPose {
    return cloneCameraPose(this.pose);
  }

  configure(options: SmoothCameraRigOptions): void {
    this.options = { ...this.options, ...options };
  }

  /** Instant cut: drops any running transition and kills the spring momentum. */
  snapTo(pose: CameraPose): CameraPose {
    this.transition.cancel();
    this.pose = cloneCameraPose(pose);
    resetVelocity(this.positionSpring.velocity);
    resetVelocity(this.targetSpring.velocity);
    return this.current;
  }

  /** Starts a timed blend from wherever the camera happens to be right now. */
  transitionTo(options: CameraTransitionOptions = {}): void {
    this.transition.start(this.pose, options);
  }

  update(deltaSeconds: number, desired: CameraPose): CameraPose {
    const step = clampDeltaSeconds(deltaSeconds, this.options.maxDeltaSeconds);
    if (step <= 0) return this.current;

    const previous = this.pose;
    const transitioning = this.transition.isActive;
    const next: CameraPose = transitioning
      ? this.transition.update(step, desired)
      : {
          position: smoothDampVec3(
            previous.position,
            desired.position,
            this.positionSpring,
            this.options.positionSmoothTime,
            step,
            this.options.maxSpeed,
          ),
          target: smoothDampVec3(
            previous.target,
            desired.target,
            this.targetSpring,
            this.options.targetSmoothTime,
            step,
            this.options.maxSpeed,
          ),
          fov: damp(previous.fov, desired.fov, this.options.fovSmoothTime, step),
        };

    // Keep the springs in sync with the transition so the hand-off carries the
    // camera momentum instead of stalling on the last transition frame.
    if (transitioning) {
      syncVelocity(this.positionSpring.velocity, previous.position, next.position, step);
      syncVelocity(this.targetSpring.velocity, previous.target, next.target, step);
    }

    next.position = this.resolveCollision(next.target, next.position);
    this.pose = next;
    return cloneCameraPose(next);
  }

  private resolveCollision(target: Vec3, position: Vec3): Vec3 {
    const raycaster = this.options.raycaster;
    if (!raycaster) return position;
    return resolveCameraPosition(target, position, raycaster, this.options.collision);
  }
}

function resetVelocity(velocity: Vec3): void {
  velocity.x = 0;
  velocity.y = 0;
  velocity.z = 0;
}

function syncVelocity(velocity: Vec3, from: Vec3, to: Vec3, step: number): void {
  velocity.x = (to.x - from.x) / step;
  velocity.y = (to.y - from.y) / step;
  velocity.z = (to.z - from.z) / step;
}
